// --------------------- 数据集构建期校验器 ------------------------------------

/** 取卡所属分区。 */
export function pileOf(card) {
  if (card.kind === 'rare') return 'rare';
  if (card.kind === 'legendary') return 'legendary';
  return card.stage;
}
